    // Sabattier: invert channels that exceed threshold
    vec3 inv = 1.0 - col.rgb;
    // Smooth inversion using a tent function around threshold
    vec3 solar = mix(col.rgb,
                     mix(col.rgb, inv, step(u_threshold, col.rgb)),
                     u_strength);
