    vec3 chrome = mix(vec3(lum * 0.5 + 0.1), vec3(lum * 0.9 + 0.1), band) * tint;
    chrome += spec * tint * 1.4;
    vec3 result = mix(col.rgb, chrome, u_metallic);
    frag = vec4(clamp(result, 0.0, 1.0), col.a);
