                float arm_len = r * 2.5;
                float star = smoothstep(arm_len, 0.0, min(adiff.x, adiff.y) * 2.5 + dist * 0.5) * anim * 0.4;
                float hue = hash(g + vec2(fl, fl * 1.7));
                vec3 color = mix(vec3(1.0), hue2rgb(hue), u_color_var);
                glitter += color * max(spark, star);
